75	// The cross objdump chain: --objdump wins, else $HYBRID_TOOLCHAIN (env or
76	// config.env) so RISC-V vendor extensions (RVV, Andes custom) decode
77	// correctly -- generic llvm-objdump on old distros may not know RVV.
78	std::string resolve_objdump(const std::string& override_path) {
79	  if (!override_path.empty()) return override_path;
80	  std::vector<std::string> cands;
81	  if (const std::string tc = config_env_value("HYBRID_TOOLCHAIN"); !tc.empty()) {
82	    cands.push_back(tc + "/bin/riscv64-unknown-elf-objdump");
83	    cands.push_back(tc + "/bin/riscv32-unknown-elf-objdump");
84	  }
85	  cands.insert(cands.end(), {"riscv64-unknown-elf-objdump",
86	                             "riscv32-unknown-elf-objdump", "llvm-objdump",
87	                             "objdump"});
88	  return find_first(cands);
89	}
