219	std::string render_llm(const std::vector<Loop>& loops,
220	                       const std::vector<LoopSyms>& syms, uint64_t total_iters,
221	                       const std::string& target_name, const Disasm& disasm,
222	                       int min_iters, bool rvv_filter) {
223	  std::string out;
224	  if (loops.empty()) return out;
225	
226	  auto pct = [&](uint64_t n) -> double {
227	    return total_iters ? 100.0 * static_cast<double>(n) /
228	                             static_cast<double>(total_iters)
229	                       : 0.0;
230	  };
231	  auto src_short = [&](const std::string& full) -> std::string {
232	    return full.empty() ? "" : src_basename(full);
233	  };
234	
235	  // Header + TL;DR
236	  {
237	    const Loop& top = loops[0];
238	    const LoopSyms& ts = syms[0];
239	    auto rvv = rvv_in_range(disasm, top.start, top.end);
240	    std::string rvv_str;
241	    if (!rvv.empty()) {
242	      std::vector<std::string> uniq;
243	      for (const auto& r : rvv)
244	        if (std::find(uniq.begin(), uniq.end(), r.mn) == uniq.end())
245	          uniq.push_back(r.mn);
246	      rvv_str = "RVV (";
247	      for (size_t i = 0; i < std::min(uniq.size(), size_t{3}); ++i) {
248	        if (i) rvv_str += ", ";
249	        rvv_str += uniq[i];
250	      }
251	      if (uniq.size() > 3)
252	        rvv_str += ", +" + std::to_string(uniq.size() - 3) + " more";
253	      rvv_str += ")";
254	    } else {
255	      rvv_str = "scalar";
256	    }
257	    std::string src_s = src_short(ts.src_start);
258	    if (src_s.empty()) src_s = "?";
259	    std::string nest_str = top.parent >= 0
260	                               ? "nested inside " +
261	                                     loops[static_cast<size_t>(top.parent)].id
262	                               : "top-level (no parent loop)";
263	    std::string child_str;
264	    if (!top.children.empty()) {
265	      child_str = "and contains " + std::to_string(top.children.size()) +
266	                  " inner loop(s): ";
267	      for (size_t i = 0; i < top.children.size(); ++i) {
268	        if (i) child_str += ", ";
269	        child_str += loops[static_cast<size_t>(top.children[i])].id;
270	      }
271	    } else {
272	      child_str = "and contains no inner loop";
273	    }
274	    appendf(out, "# HotIterationLoop Report\n");
275	    appendf(out, "target:           %s\n", target_name.c_str());
276	    appendf(out, "total_iters:      %llu\n", (unsigned long long)total_iters);
277	    appendf(out, "reported_loops:   %zu\n", loops.size());
278	    appendf(out, "min_iters:        %d\n", min_iters);
279	    appendf(out, "rvv_filter:       %s\n", rvv_filter ? "on" : "off");
280	    appendf(out, "\n## TL;DR\n");
281	    appendf(out,
282	            "Hottest loop is %s in `%s` (%s), %llu iters = %.1f%% of total. "
283	            "Body is %s. It is %s, %s.\n",
284	            top.id.c_str(), ts.fn_name.c_str(), src_s.c_str(),
285	            (unsigned long long)top.iters, pct(top.iters), rvv_str.c_str(),
286	            nest_str.c_str(), child_str.c_str());
287	    appendf(out, "\n## Loops\n");
288	  }
289	
290	  for (size_t idx = 0; idx < loops.size(); ++idx) {
291	    const Loop& loop = loops[idx];
292	    const LoopSyms& ls = syms[idx];
293	    appendf(out, "\n### %s%s  (%.1f%% of total)\n", loop.id.c_str(),
294	            idx == 0 ? " [hottest]" : "", pct(loop.iters));
295	    appendf(out, "iters:        %llu\n", (unsigned long long)loop.iters);
296	    appendf(out, "function:     %s -> %s\n", ls.sym_start.c_str(),
297	            ls.sym_end.c_str());
298	
299	    // measure: whole enclosing function (entry -> ret).
300	    if (ls.fn_entry != 0 && ls.fn_end != 0) {
301	      uint64_t ret_pc = measure_ret_pc(disasm, ls.fn_entry, ls.fn_end);
302	      appendf(out,
303	              "measure:      --pc-start 0x%llx --pc-end 0x%llx"
304	              "  (all of %s: entry -> ret)\n",
305	              (unsigned long long)ls.fn_entry, (unsigned long long)ret_pc,
306	              ls.fn_name.c_str());
307	    }
308	
309	    const std::string& sf = ls.src_start;
310	    const std::string& se = ls.src_end;
311	    if (!sf.empty() && !se.empty() && sf == se)
312	      appendf(out, "source:       %s\n", src_basename(sf).c_str());
313	    else
314	      appendf(out, "source:       %s -> %s\n",
315	              (sf.empty() ? "?" : src_basename(sf)).c_str(),
316	              (se.empty() ? "?" : src_basename(se)).c_str());
317	
318	    if (!ls.code_snippet.empty()) {
319	      std::string snippet = ls.code_snippet;
320	      if (snippet.size() > 200) snippet = snippet.substr(0, 197) + "...";
321	      appendf(out, "code:         %s\n", snippet.c_str());
322	    }
323	
324	    auto rvv = rvv_in_range(disasm, loop.start, loop.end);
325	    if (!rvv.empty()) {
326	      appendf(out, "rvv:          yes (%zu insn%s)\n", rvv.size(),
327	              rvv.size() == 1 ? "" : "s");
328	      appendf(out, "rvv_insns:\n");
329	      for (size_t i = 0; i < std::min(rvv.size(), size_t{8}); ++i)
330	        appendf(out, "  - 0x%llx  %-10s %s\n", (unsigned long long)rvv[i].pc,
331	                rvv[i].mn.c_str(), rvv[i].ops.c_str());
332	      if (rvv.size() > 8)
333	        appendf(out, "  - ... (%zu more)\n", rvv.size() - 8);
334	    } else {
335	      appendf(out, "rvv:          no\n");
336	    }
337	
338	    appendf(out, "parent:       %s\n",
339	            loop.parent >= 0 ? loops[static_cast<size_t>(loop.parent)].id.c_str()
340	                             : "-");
341	    if (!loop.children.empty()) {
342	      appendf(out, "children:     [");
343	      for (size_t i = 0; i < loop.children.size(); ++i) {
344	        if (i) appendf(out, ", ");
345	        appendf(out, "%s",
346	                loops[static_cast<size_t>(loop.children[i])].id.c_str());
347	      }
348	      appendf(out, "]\n");
349	    } else {
350	      appendf(out, "children:     []\n");
351	    }
352	
353	    auto callees = calls_in_range(disasm, loop.start, loop.end);
354	    if (!callees.empty()) {
355	      appendf(out, "calls:\n");
356	      for (size_t i = 0; i < std::min(callees.size(), size_t{8}); ++i)
357	        appendf(out, "  - 0x%llx  %s -> %s\n",
358	                (unsigned long long)callees[i].pc, callees[i].mn.c_str(),
359	                callees[i].target.c_str());
360	      if (callees.size() > 8)
361	        appendf(out, "  - ... (%zu more)\n", callees.size() - 8);
362	    } else {
363	      appendf(out, "calls:        []\n");
364	    }
365	  }
366	  return out;
367	}
368	
369	std::string render_table(const std::vector<LoopEdge>& rows,
370	                         const std::vector<LoopSyms>& syms, int min_iters,
371	                         bool rvv_filter) {
372	  std::string out;
373	  bool have_src = false;
374	  for (const auto& s : syms)
375	    if (!s.src_start.empty() || !s.src_end.empty()) have_src = true;
376	
377	  auto src_short = [&](const std::string& full) -> std::string {
378	    return full.empty() ? "" : src_basename(full);
379	  };
380	  auto srcpair = [&](const LoopSyms& s) -> std::string {
381	    std::string a = src_short(s.src_start), b = src_short(s.src_end);
382	    if (!a.empty() && a == b) return a;
383	    return (a.empty() ? "?" : a) + " -> " + (b.empty() ? "?" : b);
384	  };
385	
386	  appendf(out, "# hot loops (iters >= %d", min_iters);
387	  if (rvv_filter) appendf(out, ", RVV-only");
388	  appendf(out, "), sorted desc, top %zu\n", rows.size());
389	
390	  size_t w_iter = 5;  // strlen("iters")
391	  for (const auto& r : rows) {
392	    char buf[24];
393	    snprintf(buf, sizeof(buf), "%llu", (unsigned long long)r.iters);
394	    w_iter = std::max(w_iter, strlen(buf));
395	  }
396	  const size_t w_pc = 18;
397	  size_t w_sym = 8;  // strlen("location")
398	  for (const auto& s : syms)
399	    w_sym = std::max(w_sym, s.sym_start.size() + 4 + s.sym_end.size());
400	
401	  if (have_src) {
402	    appendf(out, "%*s | %-*s -> %-*s | %-*s | source\n",
403	            static_cast<int>(w_iter), "iters", static_cast<int>(w_pc),
404	            "start_pc", static_cast<int>(w_pc), "end_pc",
405	            static_cast<int>(w_sym), "location");
406	  } else {
407	    appendf(out, "%*s | %-*s -> %-*s | location\n", static_cast<int>(w_iter),
408	            "iters", static_cast<int>(w_pc), "start_pc",
409	            static_cast<int>(w_pc), "end_pc");
410	  }
411	  size_t sep = w_iter + 3 + w_pc + 4 + w_pc + 3 + w_sym;
412	  if (have_src) sep += 3 + 12;
413	  appendf(out, "%s\n", std::string(sep, '-').c_str());
414	
415	  for (size_t i = 0; i < rows.size(); ++i) {
416	    const LoopEdge& r = rows[i];
417	    std::string loc = syms[i].sym_start + " -> " + syms[i].sym_end;
418	    if (have_src)
419	      appendf(out, "%*llu | 0x%016llx -> 0x%016llx | %-*s | %s\n",
420	              static_cast<int>(w_iter), (unsigned long long)r.iters,
421	              (unsigned long long)r.start, (unsigned long long)r.end,
422	              static_cast<int>(w_sym), loc.c_str(), srcpair(syms[i]).c_str());
423	    else
424	      appendf(out, "%*llu | 0x%016llx -> 0x%016llx | %s\n",
425	              static_cast<int>(w_iter), (unsigned long long)r.iters,
426	              (unsigned long long)r.start, (unsigned long long)r.end,
427	              loc.c_str());
428	  }
429	  return out;
430	}
