1	// Resolve a per-host setting the way setup.sh and the test harness do: the
2	// environment wins, else the first `KEY=value` assignment in the gitignored
3	// per-host config.env. This lets `./andesim` find the external qemu/vsim
4	// (QEMU_BIN_DIR / VSIM_BIN_DIR) without a prior `source ./setup.sh`, matching
5	// how cmd_doctor already resolves HYBRID_TOOLCHAIN.
6	#ifndef ANDESIM_CONFIG_ENV_HPP
7	#define ANDESIM_CONFIG_ENV_HPP
8	
9	#include <cstdlib>
10	#include <filesystem>
11	#include <fstream>
12	#include <string>
13	#include <string_view>
14	
15	#include "repo_root.hpp"
16	
17	namespace andes_sim {
18	
19	// $key (non-empty) wins; else the first `key=value` line in `config_file`
20	// (leading whitespace and `# comment` lines ignored). Empty string if neither
21	// yields a value; a missing config file is not an error.
22	inline std::string config_env_value(std::string_view key,
23	                                    const std::filesystem::path& config_file) {
24	  const std::string k{key};
25	  if (const char* e = std::getenv(k.c_str()); e && *e) return e;
26	
27	  std::ifstream f(config_file);
28	  if (!f) return "";
29	  const std::string prefix = k + "=";
30	  std::string line;
31	  while (std::getline(f, line)) {
32	    const std::size_t b = line.find_first_not_of(" \t");
33	    if (b == std::string::npos || line[b] == '#') continue;
34	    if (line.compare(b, prefix.size(), prefix) != 0) continue;
35	    std::string val = line.substr(b + prefix.size());
36	    val.erase(val.find_last_not_of(" \t\r") + 1);  // right-trim (npos+1 == 0)
37	    return val;
38	  }
39	  return "";
40	}
41	
42	// Same, against the repo's own config.env.
43	inline std::string config_env_value(std::string_view key) {
44	  return config_env_value(key, repo_root() / "config.env");
45	}
46	
47	}  // namespace andes_sim
48	
49	#endif  // ANDESIM_CONFIG_ENV_HPP
