1	// Runtime engine discovery -- the hot-plug seam.
2	//
3	// discover_engines() returns the built-in qemu descriptor plus every engine
4	// found by scanning a directory and asking each binary to self-report via
5	// `--describe` (falling back to a <bin>.json sidecar). No engine is compiled
6	// into the framework; dropping a freshly built sim_<cfg> into the scan dir
7	// makes it appear here with no andesim rebuild.
8	//
9	// Scan dir: $ANDESIM_ENGINES_DIR (colon-separated; REPLACES the default and
10	// accepts any executable) if set, else vsim_scan_dir() (filtered to sim_*
11	// binaries) -- $VSIM_BIN_DIR, the external prebuilt vsim build dir mirroring
12	// $QEMU_BIN_DIR.
13	#ifndef ANDESIM_ENGINE_REGISTRY_HPP
14	#define ANDESIM_ENGINE_REGISTRY_HPP
15	
16	#include <filesystem>
17	#include <string>
18	#include <vector>
19	
20	#include "elf_syms.hpp"
21	#include "engine_descriptor.hpp"
22	#include "strutil.hpp"
23	
24	namespace andes_sim {
25	
26	// Built-in functional engine ids (the qemu64/qemu32 pair). Declared once here so
27	// builtin_qemu_arch, the hybrid plan steps, and `run --mode fast` acceptance all
28	// agree -- a renamed literal would otherwise break find_engine() lookups only at
29	// run time.
30	inline constexpr const char* kQemuId64 = "qemu64";
31	inline constexpr const char* kQemuId32 = "qemu32";
32	
33	struct Discovery {
34	  std::vector<EngineDescriptor> engines;   // deduped by id; qemu first
35	  std::vector<std::string> warnings;       // binaries that failed to describe
36	};
37	
38	Discovery discover_engines();
39	
40	// Directory discover_engines() scans for sim_* engines when $ANDESIM_ENGINES_DIR
41	// is unset: VSIM_BIN_DIR (the external prebuilt vsim build, mirroring
42	// QEMU_BIN_DIR) resolved env-first then from `config_file` (default: the repo
43	// config.env); empty when unset everywhere.
44	std::filesystem::path vsim_scan_dir();
45	std::filesystem::path vsim_scan_dir(const std::filesystem::path& config_file);
46	
47	// The bundled qemu descriptor (no directory scan, no --describe subprocess).
48	// discover_engines() seeds the registry with it; `run --mode fast` resolves
49	// qemu through it directly, paying none of the Verilator-engine discovery cost.
50	// builtin_qemu_arch(xlen) builds the rv64 "qemu64" (xlen=64) or rv32 "qemu32"
51	// (xlen=32, qemu-system-riscv32); builtin_qemu() is the rv64 default.
52	EngineDescriptor builtin_qemu_arch(int xlen);
53	EngineDescriptor builtin_qemu();
54	
55	// Rewrite a discovered engine's identity from the third-party simulator name to
56	// the product name: type "verilator" -> "vsim", id "verilator:<cfg>" ->
57	// "vsim:<cfg>". discover_engines() applies this once, before the id is used for
58	// dedup or shown anywhere, so every downstream consumer (list / --engine /
59	// errors / run banner) speaks "vsim" and a user never sees "verilator". Any
60	// other backend (qemu, a drop-in alioth/sid) passes through untouched.
61	inline void normalize_engine_label(EngineDescriptor& d) {
62	  if (d.type == "verilator") d.type = "vsim";
63	  if (d.id.rfind("verilator:", 0) == 0) d.id = "vsim:" + d.id.substr(10);
64	  // The CLI exposes the marker delimiter as `--trigger marker`; some engines
65	  // report it under their internal name "csr" via --describe. Speak the CLI's
66	  // vocabulary in list / doctor too, like verilator -> vsim above.
67	  for (std::string& t : d.triggers)
68	    if (t == "csr") t = "marker";
69	}
70	
71	// Select the cycle-accurate engine for `run --mode cycle` from an
72	// already-discovered set (pure; spawns nothing). With `want_id` empty, default
73	// to the sole cycle-accurate engine -- erroring if there are none or more than
74	// one (ambiguous). With `want_id` set, that engine must exist and be
75	// cycle-accurate. Returns nullptr and sets `err` (naming the available
76	// cycle-accurate ids) on any failure; the returned pointer aliases into
77	// `engines`, so it must outlive the result.
78	inline const EngineDescriptor* resolve_accurate_engine(
79	    const std::vector<EngineDescriptor>& engines, const std::string& want_id,
80	    std::string& err) {
81	  auto is_accurate = [](const EngineDescriptor& e) {
82	    return e.kind == "cycle-accurate";
83	  };
84	  auto accurate_ids = [&] {
85	    std::vector<std::string> ids;
86	    for (const EngineDescriptor& e : engines)
87	      if (is_accurate(e)) ids.push_back(e.id);
88	    return join(ids, ", ");
89	  };
90	
91	  if (!want_id.empty()) {  // explicit --engine
92	    for (const EngineDescriptor& e : engines) {
93	      if (e.id != want_id) continue;
94	      if (is_accurate(e)) return &e;
95	      err = "engine '" + want_id + "' is " +
96	            (e.kind.empty() ? "not cycle-accurate" : e.kind) +
97	            "; a cycle-accurate engine is required";
98	      return nullptr;
99	    }
100	    std::string have = accurate_ids();
101	    err = "no engine '" + want_id + "'" +
102	          (have.empty() ? " (no cycle-accurate engines found)"
103	                        : " (cycle-accurate engines: " + have + ")");
104	    return nullptr;
105	  }
106	
107	  // No --engine: default to the sole cycle-accurate engine.
108	  const EngineDescriptor* sole = nullptr;
109	  int n = 0;
110	  for (const EngineDescriptor& e : engines)
111	    if (is_accurate(e)) { sole = &e; ++n; }
112	  if (n == 1) return sole;
113	  if (n == 0)
114	    err = "model cycle: no cycle-accurate engine found "
115	          "(point VSIM_BIN_DIR in config.env at your external vsim build/)";
116	  else
117	    err = "model cycle: multiple cycle-accurate engines; select one with "
118	          "--engine (have: " + accurate_ids() + ")";
119	  return nullptr;
120	}
121	
122	// Reject an ELF whose class width (rv32/rv64) does not match the engine it would
123	// run on -- a clear pre-flight error instead of a cryptic "not of ELFCLASSxx"
124	// from deep inside the engine. Both directions. Returns "" when they agree, when
125	// the ELF is unreadable/not-ELF (reported elsewhere), or when the engine
126	// declares no xlen (cannot judge). Shared by cycle, hybrid, and profile: one
127	// wording.
128	inline std::string elf_engine_arch_error(const std::string& elf,
129	                                         const EngineDescriptor& eng) {
130	  const int ex = elf_xlen(elf);
131	  if (ex == 0 || eng.xlen == 0 || ex == eng.xlen) return "";
132	  char buf[256];
133	  std::snprintf(buf, sizeof(buf),
134	                "ELF is rv%d but engine '%s' is rv%ld -- pick a matching engine "
135	                "or an rv%d ELF",
136	                ex, eng.id.c_str(), eng.xlen, ex);
137	  return buf;
138	}
139	
140	}  // namespace andes_sim
141	
142	#endif  // ANDESIM_ENGINE_REGISTRY_HPP
143

