// Placeholder substitution for engine invoke templates (minus QEMU2). The
// argv *shape* lives in each engine's `invoke` template (from
// `--describe`, see docs/engine_interface.md) and build_argv fills the
// {placeholders} from a context map. The framework thus keeps zero per-engine
// argv code: a new engine ships its own template.
#ifndef ANDESIM_ARGV_HPP
#define ANDESIM_ARGV_HPP

#include <cctype>
#include <cstdio>
#include <cstring>
#include <map>
#include <string>
#include <vector>

namespace andes_sim {

// POSIX shell-quote one arg so a rendered command line is copy-pasteable. A
// token of only safe characters passes through; anything else (empty, spaces,
// quotes, globs) is wrapped in single quotes with embedded `'` escaped as
// '\''. Used by render_argv for the --dry-run command preview.
inline std::string shell_quote(const std::string& s) {
  if (!s.empty()) {
    bool safe = true;
    for (char c : s)
      if (!std::isalnum(static_cast<unsigned char>(c)) &&
          !std::strchr("_@%+=:,./-", c)) {
        safe = false;
        break;
      }
    if (safe) return s;
  }
  std::string out = "'";
  for (char c : s) out += (c == '\'') ? "'\\''" : std::string(1, c);
  out += "'";
  return out;
}

// Join an argv into one shell-quoted line (each token via shell_quote).
inline std::string render_argv(const std::vector<std::string>& argv) {
  std::string out;
  for (size_t i = 0; i < argv.size(); ++i) {
    if (i) out += ' ';
    out += shell_quote(argv[i]);
  }
  return out;
}

// Print the dry-run preview: the exact command(s) andesim WOULD spawn, each
// shell-quoted and labeled, executing nothing. Shared by run and profile so
// the preview format is identical; `labels[i]` annotates `argvs[i]` (e.g.
// "standalone [qemu64]", "profile [vsim:x]"). Always returns 0 -- a dry run
// reports the plan, it does not run it.
inline int print_dry_run(const std::vector<std::vector<std::string>>& argvs,
                         const std::vector<std::string>& labels) {
  std::printf("[andesim] dry-run: %zu command(s), not executed\n", argvs.size());
  for (size_t i = 0; i < argvs.size(); ++i) {
    std::printf("# command %zu/%zu: %s\n", i + 1, argvs.size(),
                labels[i].c_str());
    std::printf("%s\n", render_argv(argvs[i]).c_str());
  }
  return 0;
}

// Substitute every "{key}" in `tmpl`'s args with `ctx.at(key)`. A key may
// appear anywhere in an arg (so "mem-path={mmap},size={mmap_size}" expands in
// one arg) and more than once. Recognised keys come from `ctx`; a "{key}" with
// no matching ctx entry is an error (returns {} and sets `err`). On success
// `err` is cleared and the fully-resolved argv is returned.
std::vector<std::string> build_argv(const std::vector<std::string>& tmpl,
                                    const std::map<std::string, std::string>& ctx,
                                    std::string& err);

}  // namespace andes_sim

#endif  // ANDESIM_ARGV_HPP

// andesim leveled logging.
//
// The scale mirrors the vsim engines' --log-level option so users learn one
// scheme: 0=trace 1=debug 2=info 3=warn 4=error 5=critical 6=off. A message
// prints when its level >= the threshold; the default threshold is info.
//
// What lives at which level (driver policy):
//   info  -- the answers: program output relays, the cycle figure,
//            --dry-run/--verify results. Program output itself is never
//            gated (it is the program's, not a log).
//   debug -- driver chatter: the hybrid banner, the mmap line, PASS lines,
//            verify progress notes.
//   warn  -- degradations: unsupported-CSR warnings, skipped engines.
// Fatal errors are not gated: they accompany a non-zero exit.
#ifndef ANDESIM_LOG_HPP
#define ANDESIM_LOG_HPP

#include <string>

namespace andes_sim {

enum LogLevel {
  kLogTrace = 0,
  kLogDebug = 1,
  kLogInfo = 2,
  kLogWarn = 3,
  kLogError = 4,
  kLogCritical = 5,
  kLogOff = 6,
};

// Set the process-wide threshold from the CLI value. "" keeps the default
// (info). Returns false (and leaves the threshold alone) when the value is
// not an integer in 0..6.
bool set_log_threshold(const std::string& cli_value);

// The current threshold (0..6). Used to forward the level to child engines.
int log_threshold();

// True when a message at `level` should print.
bool log_on(int level);

// Open the --log-file sink. Once open, EVERY log_line/log_result message --
// all levels, even below the console threshold -- is appended to the file
// with a UTC timestamp and a level tag. Returns false if the file cannot be
// opened (the sink stays off). Empty path is a no-op success.
bool set_log_file(const std::string& path);

// The open sink's path, or "" when none.
const std::string& log_file_path();

// Emit one chatter line to stderr when `level` passes the threshold. Pass
// the complete line text (including its "[andesim] " prefix), without the
// trailing newline. Always mirrored to the --log-file sink.
void log_line(int level, const char* fmt, ...)
    __attribute__((format(printf, 2, 3)));

// Emit one RESULT line (the cycle figure, PASS/verify verdicts) to stdout
// when `level` passes the threshold. Always mirrored to the sink.
void log_result(int level, const char* fmt, ...)
    __attribute__((format(printf, 2, 3)));

}  // namespace andes_sim

#endif  // ANDESIM_LOG_HPP

